"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["67206"],{30984(e){e.exports=JSON.parse('{"id":"FIN-1429","slug":"serviceable-available-market","term":"Serviceable Available Market (SAM)","also_known_as":["SAM"],"difficulty":"Advanced","definition":"Serviceable available market (SAM) is the portion of the total addressable market that a company can realistically target with its current products, business model and geographic reach.","explanation":["Total addressable market estimates the entire revenue opportunity for a type of product. SAM narrows this down to the customers the company\'s specific offering can actually serve.","For example, the global market for accounting software might be worth 1,000,000,000 a year. A company whose software is designed for small businesses and sold only in English-speaking countries might have a SAM of 200,000,000, because larger companies and other regions are outside its reach.","SAM is shaped by factors such as the product\'s features, price point, distribution channels, language, regulations and the customer segments the company targets.","SAM helps companies and investors judge a realistic growth opportunity. A huge total market means little if the company can only serve a small part of it. Expanding into new regions or customer segments, or adding product features, can increase SAM over time."],"note":"","total":1500,"prev":{"slug":"series-b","term":"Series B"},"next":{"slug":"serviceable-obtainable-market","term":"Serviceable Obtainable Market (SOM)"}}')}}]);